-- Topic: Tax-Exempt Organizations
-- Difficulty: 9E / 15M / 6H
-- Bloom's: L1:8 / L2:9 / L3:8 / L4:5

BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Section 501(h) expenditure test election for lobbying safe harbor
(3, 'Tax-Exempt Organizations', 'River Valley Education Foundation, a 501(c)(3) with $600,000 in exempt purpose expenditures, elects the Section 501(h) expenditure test to measure lobbying compliance. Under this election, how are lobbying limits determined?', '["Lobbying limits are based on a sliding-scale percentage of exempt purpose expenditures, with a maximum cap", "Lobbying limits are fixed at 5% of total organizational revenue", "The organization may spend an unlimited amount on lobbying activities", "Lobbying limits are set at whatever amount the board of directors approves"]'::jsonb, 0, 'Under IRC Section 501(h), organizations that elect the expenditure test measure lobbying limits using a sliding-scale percentage of exempt purpose expenditures, capped at $1,000,000 regardless of size. This replaces the vague ''substantial part'' test of Section 501(c)(3) with specific dollar thresholds. Unlike the fixed 5% in choice B, the sliding scale starts at 20% of the first $500,000 and decreases for higher expenditure levels.', 'medium', 2),

-- Q2: easy / L1 — Churches, schools, hospitals as automatic public charities
(3, 'Tax-Exempt Organizations', 'Which types of 501(c)(3) organizations are automatically classified as public charities regardless of their funding sources?', '["Only organizations with annual revenues exceeding $5 million", "Churches, schools, and hospitals", "Any organization that has existed for more than five years", "Organizations with at least 100 individual donors"]'::jsonb, 1, 'Under IRC Section 509(a)(1), churches, schools, and hospitals are automatically classified as public charities without needing to satisfy the one-third public support test. This classification is based on the inherent public nature of these institutions. Unlike choice D, which suggests a donor count requirement, the classification depends on organizational type, not funding metrics.', 'easy', 1),

-- Q3: medium / L3 — Personal property rents UBIT 10% incidental rule
(3, 'Tax-Exempt Organizations', 'Lakeside Historical Society, a 501(c)(3), leases a furnished building to a commercial tenant. The annual lease payments total $100,000, of which $15,000 is allocated to personal property (furniture and equipment) and $85,000 to real property. How is the personal property rent treated for UBIT purposes?', '["The entire $100,000 is excluded from UBIT because the lease is a single mixed-use arrangement", "Only the $15,000 personal property portion is included in UBIT while the real property rent remains excluded", "The $15,000 personal property rent is included in UBIT because it exceeds 10% of total rents under the lease", "The entire $100,000 is subject to UBIT because any personal property component taints the full lease"]'::jsonb, 2, 'Under IRC Section 512(b)(3), rents from real property are generally excluded from UBIT, but rents from personal property are included unless incidental. Personal property rents are considered incidental only when they are less than 10% of total rents under the lease. Here, $15,000/$100,000 = 15%, exceeding the 10% threshold, so the personal property rent is included in UBIT. Unlike choice A, the personal property component is not automatically excluded in a mixed lease.', 'medium', 3),

-- Q4: medium / L2 — Supporting organizations Section 509(a)(3)
(3, 'Tax-Exempt Organizations', 'Bright Horizons Alliance is organized and operated exclusively to raise funds and provide administrative support for three established 501(c)(3) public charities. Under Section 509(a)(3), how is Bright Horizons Alliance classified?', '["As a private foundation because it does not directly serve the public", "As a private operating foundation with special distribution requirements", "As a conduit organization subject to intermediate sanctions", "As a supporting organization classified as a public charity"]'::jsonb, 3, 'Under IRC Section 509(a)(3), an organization operated exclusively to support one or more public charities qualifies as a supporting organization and is classified as a public charity. This avoids the private foundation restrictions and excise taxes. Unlike choice A, the organization does not need direct public service to avoid private foundation status — operating exclusively in support of public charities satisfies the test.', 'medium', 2),

-- Q5: medium / L3 — Controlled entity payments treated as UBIT
(3, 'Tax-Exempt Organizations', 'Heritage Arts Council, a 501(c)(3), owns 90% of the voting stock in Heritage Printing LLC. Heritage Printing pays $200,000 in annual rent to the Council for office space, but comparable market rent would be $120,000. How is the rent payment treated for UBIT purposes?', '["The excess rent of $80,000 above fair market value is treated as unrelated business income", "The entire $200,000 is excluded as passive rental income from real property", "The entire $200,000 is included in UBIT because the subsidiary is a controlled entity", "Only $120,000 (the fair market value portion) is included in UBIT"]'::jsonb, 0, 'Under IRC Section 512(b)(13), rent received from a controlled subsidiary (80%+ ownership) is treated as UBIT to the extent it exceeds fair market value. Heritage Arts Council owns 90%, making Heritage Printing a controlled entity. The $80,000 excess ($200,000 minus $120,000 FMV) is included in UBIT. Unlike choice B, the passive income exclusion does not fully apply to payments from controlled entities when they exceed FMV.', 'medium', 3),

-- Q6: easy / L2 — Form 990 filing deadline for calendar-year filers
(3, 'Tax-Exempt Organizations', 'Valley Community Foundation, a calendar-year 501(c)(3), needs to file its annual Form 990. By what date must the foundation file, assuming no extension is requested?', '["January 31 of the following year", "March 15 of the following year", "April 15 of the following year", "May 15 of the following year"]'::jsonb, 3, 'Under IRC Section 6033, Form 990 is due on the 15th day of the 5th month after the end of the organization''s tax year. For calendar-year organizations, this is May 15. Unlike choice C (April 15), which is the individual income tax deadline, the Form 990 deadline provides additional time for exempt organizations to compile their annual information returns.', 'easy', 2),

-- Q7: hard / L3 — Rebuttable presumption of reasonableness three conditions
(3, 'Tax-Exempt Organizations', 'Coastal Relief Network, a 501(c)(3), sets its new CEO''s compensation at $650,000. The compensation committee consists entirely of independent board members who obtained salary surveys from three comparable organizations, documented their analysis, and approved the package by recorded vote. The IRS later challenges the compensation as an excess benefit. Under Section 4958, how does the rebuttable presumption of reasonableness affect the analysis?', '["The presumption is irrelevant because all CEO compensation above $500,000 is automatically an excess benefit", "The burden shifts to the IRS to prove the compensation is unreasonable, since the organization satisfied all three requirements for the presumption", "The presumption eliminates any possibility of excise taxes regardless of the actual compensation amount", "The presumption only applies if the compensation is below the median of comparable organizations"]'::jsonb, 1, 'Under IRC Section 4958 and Treasury Regulations, the rebuttable presumption of reasonableness is established when three conditions are met: (1) approval by an independent board or committee, (2) reliance on appropriate comparability data, and (3) contemporaneous documentation of the decision. When all three are satisfied, the burden shifts to the IRS to prove the compensation is unreasonable. Unlike choice C, the presumption is rebuttable, not absolute — the IRS can still prevail with sufficient evidence.', 'hard', 3),

-- Q8: medium / L3 — NOL deduction computed using only UBI items
(3, 'Tax-Exempt Organizations', 'Greenway Conservation Trust, a 501(c)(3), had $40,000 of unrelated business income in 2025 and $60,000 of unrelated business losses in 2024 (no other UBI in prior years). The trust also had $200,000 of investment income in 2024. When computing its 2025 UBIT, how is the 2024 net operating loss applied?', '["The full $60,000 NOL offsets the 2025 UBI, and $200,000 investment income reduces the remaining carryforward", "No NOL is available because the 2024 investment income already absorbed the loss", "Only unrelated business losses are included in the NOL computation, so the $60,000 NOL offsets $40,000 of UBI with $20,000 carrying forward", "The NOL cannot be carried forward because exempt organizations are not permitted NOL deductions"]'::jsonb, 2, 'Under IRC Section 512(b)(6), the NOL deduction for UBIT is computed using only unrelated business income and loss items. The $200,000 investment income from 2024 is excluded from the UBI computation and does not absorb the NOL. The $60,000 unrelated business loss carries forward and offsets the $40,000 of 2025 UBI, leaving $20,000 to carry forward. Unlike choice B, investment income is excluded from the NOL calculation.', 'medium', 3),

-- Q9: easy / L1 — Dissolution clause requirement for organizational test
(3, 'Tax-Exempt Organizations', 'What must a 501(c)(3) organization''s governing documents provide regarding asset distribution upon dissolution?', '["Assets must be distributed equally among the organization''s members", "Assets must be returned to the original donors", "Assets may be distributed to any entity at the board''s discretion", "Assets must be distributed to another exempt organization or to the government"]'::jsonb, 3, 'Under IRC Section 501(c)(3) and Treasury Regulation 1.501(c)(3)-1(b)(4), the organizational test requires a dissolution clause providing that assets will be distributed to another exempt organization or to the government upon dissolution. This ensures assets remain dedicated to charitable purposes. Unlike choice A, assets cannot be distributed to members, as this would constitute private inurement.', 'easy', 1),

-- Q10: easy / L1 — Private inurement prohibition definition
(3, 'Tax-Exempt Organizations', 'What does the private inurement prohibition under Section 501(c)(3) prevent?', '["Net earnings of the organization from benefiting any private shareholder or individual who is an insider", "The organization from earning any revenue from commercial activities", "The organization from investing in publicly traded securities", "The organization from hiring paid employees"]'::jsonb, 0, 'Under IRC Section 501(c)(3), no part of the net earnings of a tax-exempt organization may inure to the benefit of any private shareholder or individual — meaning insiders such as founders, officers, directors, or persons with substantial influence. Unlike choice B, exempt organizations may earn commercial revenue; the prohibition targets insider enrichment, not commercial activity itself.', 'easy', 1),

-- Q11: easy / L1 — Form 990-PF required for all private foundations
(3, 'Tax-Exempt Organizations', 'Which annual information return must all private foundations file regardless of their size?', '["Form 990", "Form 990-PF", "Form 990-EZ", "Form 990-N (e-Postcard)"]'::jsonb, 1, 'Under IRC Section 6033, all private foundations must file Form 990-PF regardless of their gross receipts or total assets. This detailed return includes excise tax computations under Sections 4940 through 4945. Unlike Form 990-N (choice D), which is a simplified electronic notice for small organizations with gross receipts of $50,000 or less, Form 990-PF requires full financial disclosure.', 'easy', 1),

-- Q12: hard / L4 — Intermediate sanctions 25% initial + 200% additional + manager tax analysis
(3, 'Tax-Exempt Organizations', 'Sunrise Health Foundation, a 501(c)(3), pays its CFO a $400,000 bonus on top of a $300,000 salary. An independent analysis determines total reasonable compensation is $450,000, making the excess benefit $250,000. The CFO does not return the excess benefit within the taxable period. The foundation''s board chair knowingly approved the transaction. Evaluate the total excise tax exposure across all parties under Section 4958.', '["25% initial tax on the CFO ($62,500) plus 10% tax on the board chair ($25,000, capped at $20,000)", "200% tax on the CFO ($500,000) plus 25% initial tax on the board chair ($62,500)", "25% initial tax ($62,500) plus 200% additional tax ($500,000) on the CFO, plus 10% tax on the board chair (capped at $20,000), totaling $582,500", "Only the 25% initial tax on the CFO ($62,500) applies because the board acted in good faith"]'::jsonb, 2, 'Under IRC Section 4958, the disqualified person (CFO) faces a 25% initial tax ($62,500) and, if uncorrected, a 200% additional tax ($500,000) on the $250,000 excess benefit. The organization manager (board chair) who knowingly participated owes 10% of the excess benefit, capped at $20,000 per transaction. Total exposure: $62,500 + $500,000 + $20,000 = $582,500. Unlike choice A, the additional 200% tax applies because the CFO failed to correct within the taxable period.', 'hard', 4),

-- Q13: medium / L3 — Research exclusion requires public availability for universities
(3, 'Tax-Exempt Organizations', 'Northern University, a 501(c)(3), conducts pharmaceutical research under a $2 million contract with a private drug company. The research findings are proprietary and available only to the sponsoring company. Does this research income qualify for the UBIT research exclusion?', '["Yes, because all research conducted by a university is automatically excluded from UBIT", "Yes, because the research is performed under a contract, which qualifies as a service engagement", "No, because the university should not be conducting for-profit commercial research", "No, because the research exclusion for universities requires that results be freely available to the public"]'::jsonb, 3, 'Under IRC Section 512(b)(8), research income is excluded from UBIT for colleges and universities only when the research results are freely available to the general public. Proprietary research for a single private company does not meet this requirement. Unlike choice A, the exclusion is not automatic for universities — the public availability condition must be satisfied for the exclusion to apply.', 'medium', 3),

-- Q14: medium / L2 — Public charity one-third support test Section 509(a)(1)
(3, 'Tax-Exempt Organizations', 'Hope Foundation, a 501(c)(3), received $1,200,000 in total support over four years: $500,000 from government grants, $300,000 from public contributions, and $400,000 from investment income. Under the one-third support test of Section 509(a)(1), does Hope Foundation qualify as a public charity?', '["Yes, because public and government support ($800,000) exceeds one-third of total support ($400,000)", "No, because investment income disqualifies the organization from public charity status", "No, because government grants are not counted as public support under the one-third test", "Yes, but only if the organization also satisfies the facts and circumstances test"]'::jsonb, 0, 'Under IRC Section 509(a)(1) and Section 170(b)(1)(A)(vi), an organization qualifies as a public charity if it receives at least one-third of its total support from government sources and public contributions. Here, $800,000/$1,200,000 = 66.7%, which exceeds the one-third threshold. Unlike choice C, government grants are specifically included as qualifying public support under this test.', 'medium', 2),

-- Q15: easy / L1 — Royalties exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'Under Section 512, which type of passive income is specifically excluded from unrelated business taxable income?', '["Income from services provided to the general public", "Revenue from regularly operated commercial enterprises", "Royalties received from licensing the organization''s intellectual property", "Fees from consulting engagements with for-profit businesses"]'::jsonb, 2, 'Under IRC Section 512(b)(2), royalties are specifically excluded from UBIT as a form of passive income. This includes payments received for the right to use intangible property such as trademarks, patents, or copyrights. Unlike choice A, income from services to the public typically meets the trade-or-business prong of the three-part UBIT test and is not a statutory exclusion.', 'easy', 1),

-- Q16: hard / L4 — Section 4945 taxable expenditures grant to non-charity without expenditure responsibility
(3, 'Tax-Exempt Organizations', 'Willow Creek Foundation, a private foundation, makes a $150,000 grant to Green Planet Initiative, a 501(c)(4) social welfare organization, to fund a community recycling program. The foundation does not exercise expenditure responsibility over the grant. Evaluate whether this grant constitutes a taxable expenditure under Section 4945 and the resulting tax consequences.', '["The grant is not a taxable expenditure because 501(c)(4) organizations share a similar charitable purpose", "The grant is a taxable expenditure because a private foundation must exercise expenditure responsibility when granting to non-501(c)(3) organizations, resulting in a 20% excise tax ($30,000)", "The grant is permissible as long as total grants do not exceed the foundation''s 5% minimum distribution requirement", "The grant is not a taxable expenditure because the recycling program serves a charitable purpose regardless of the recipient''s tax classification"]'::jsonb, 1, 'Under IRC Section 4945(d)(4) and (h), grants by a private foundation to non-501(c)(3) organizations are taxable expenditures unless the foundation exercises expenditure responsibility — requiring the grantee to account for funds and ensuring charitable use. Without expenditure responsibility, the $150,000 grant triggers a 20% excise tax ($30,000). Unlike choice D, the charitable nature of the program does not excuse the expenditure responsibility requirement when the grantee is not a 501(c)(3).', 'hard', 4),

-- Q17: medium / L2 — Convenience exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'State Medical Center, a 501(c)(3) hospital, operates a cafeteria on its premises that serves meals to patients, their families, and hospital employees during visiting hours. The cafeteria generates $180,000 in annual revenue. Under Section 513, does the convenience exclusion apply to exempt this revenue from UBIT?', '["No, because the cafeteria is open to families who are not members, students, or employees", "No, because any food service operation generating over $50,000 is automatically subject to UBIT", "Yes, but only if the cafeteria operates at a loss", "Yes, because the cafeteria is operated primarily for the convenience of patients and hospital employees"]'::jsonb, 3, 'Under IRC Section 513(a)(2), an activity conducted primarily for the convenience of members, students, patients, officers, or employees is excluded from UBIT. A hospital cafeteria serving patients, their families, and employees during visiting hours meets this convenience test. Unlike choice A, the convenience exclusion extends to those who are on the premises in connection with the exempt function, including patients'' families.', 'medium', 2),

-- Q18: hard / L4 — Private foundation presumption and rebuttal path
(3, 'Tax-Exempt Organizations', 'New Horizons Community Fund, a newly formed 501(c)(3), received its determination letter from the IRS. The organization''s founder contributed 85% of its funding, with the remaining 15% from small public donations. The organization has not applied for public charity classification. Evaluate New Horizons'' classification and the steps required to change it.', '["The organization is automatically a public charity because it has a valid IRS determination letter", "The organization is a private operating foundation because the founder provides most of the funding", "The organization is classified as a social welfare organization under Section 501(c)(4)", "The organization is presumed to be a private foundation and must demonstrate it meets a public charity test with broader public support to rebut the presumption"]'::jsonb, 3, 'Under IRC Section 509(a), all 501(c)(3) organizations are presumed to be private foundations unless they demonstrate qualification as a public charity. With 85% founder funding, New Horizons cannot meet the one-third public support test of Section 509(a)(1). To rebut the presumption, it must broaden its donor base to meet a support test or qualify as a supporting organization under Section 509(a)(3). Unlike choice A, a determination letter alone does not establish public charity status.', 'hard', 4),

-- Q19: medium / L3 — Bingo games exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'Eastside Youth Center, a 501(c)(3), holds weekly bingo nights that generate $75,000 annually. State law permits nonprofit bingo, and no commercial bingo parlors operate in the jurisdiction. Paid staff members run the bingo games each week. Does the bingo income qualify for the UBIT exclusion under Section 513?', '["Yes, because bingo conducted where commercial bingo is not ordinarily carried out in the jurisdiction is excluded from UBIT", "No, because the bingo exclusion only applies when volunteers run the games", "No, because weekly frequency makes the bingo a regularly carried-on trade or business subject to UBIT", "Yes, but only if the bingo proceeds are used exclusively for charitable purposes"]'::jsonb, 0, 'Under IRC Section 513(f), legal bingo games are excluded from UBIT when bingo is not ordinarily carried out on a commercial basis in the jurisdiction. Unlike the volunteer labor exclusion of Section 513(a)(1), the bingo exclusion does not require volunteer staffing — it depends on whether commercial bingo operates in the area. Choice B incorrectly conflates the volunteer exclusion with the separate bingo exclusion.', 'medium', 3),

-- Q20: hard / L4 — Foundation manager 5% tax for self-dealing participation
(3, 'Tax-Exempt Organizations', 'Patterson Family Foundation''s executive director, who serves on the board, authorizes the foundation to lease office space from the founder''s real estate company at fair market rent of $5,000 per month ($60,000 annually). The executive director reviewed market comparables and believed the lease was permissible because rent was at FMV. The IRS identifies this as self-dealing. Analyze the tax consequences for the executive director under Section 4941.', '["No tax liability because the executive director relied on market comparables in good faith", "A 5% initial tax on $60,000 ($3,000) for knowingly participating in self-dealing, because the nature of the transaction determines self-dealing regardless of price", "A 10% initial tax on $60,000 ($6,000) as the self-dealer", "Only the founder is liable; board members have no personal tax exposure for self-dealing"]'::jsonb, 1, 'Under IRC Section 4941(a)(2), a foundation manager who knowingly participates in self-dealing faces a 5% initial tax on the amount involved per year. Self-dealing is determined by the nature of the transaction — any lease between the foundation and a disqualified person violates Section 4941 regardless of FMV pricing. The executive director''s belief that FMV made it permissible does not negate knowing participation. Unlike choice C, the 10% rate applies to the self-dealer (the founder), not the manager.', 'hard', 4),

-- Q21: medium / L2 — Form 990 vs Form 990-EZ filing thresholds
(3, 'Tax-Exempt Organizations', 'Meadow Springs Outreach, a 501(c)(3) public charity, has gross receipts of $180,000 and total assets of $450,000 for the current year. Which annual information return is this organization required to file?', '["Form 990 (full return) because total assets exceed $200,000", "Form 990-N (e-Postcard) because gross receipts are under $200,000", "Form 990-EZ because gross receipts are under $200,000 and total assets are under $500,000", "Form 990-PF because total assets exceed $250,000"]'::jsonb, 2, 'Under IRC Section 6033, Form 990-EZ may be filed when gross receipts are less than $200,000 AND total assets are less than $500,000. Meadow Springs meets both thresholds ($180,000 < $200,000 and $450,000 < $500,000). Form 990 (choice A) is required only when gross receipts are $200,000 or more OR total assets are $500,000 or more. Unlike choice B, the Form 990-N threshold is $50,000 or less in gross receipts.', 'medium', 2),

-- Q22: medium / L2 — Form 8868 automatic 6-month extension
(3, 'Tax-Exempt Organizations', 'Prairie Hills Foundation, a calendar-year 501(c)(3), realizes it cannot complete its Form 990 by the May 15 filing deadline. The organization''s accountant files Form 8868 requesting additional time. How much additional time does Form 8868 provide?', '["A 30-day extension only", "A 3-month extension with the option to request one additional 3-month extension", "No extension is available for Form 990 filers", "An automatic 6-month extension"]'::jsonb, 3, 'Under IRC Section 6081 and Form 8868 instructions, tax-exempt organizations may request an automatic 6-month extension for filing Form 990 by submitting Form 8868 by the original due date. For calendar-year filers, this extends the deadline from May 15 to November 15. Unlike choice B, the current Form 8868 provides a single 6-month automatic extension rather than two separate 3-month extensions.', 'medium', 2),

-- Q23: hard / L4 — Organizational test failure despite passing operational test
(3, 'Tax-Exempt Organizations', 'Civic Progress Alliance''s articles of incorporation state it is organized for ''charitable, educational, and any other lawful purposes.'' In practice, the organization spends 95% of its resources on educational programs for underprivileged youth. The IRS denies the 501(c)(3) application. Evaluate why the organization fails to qualify despite its charitable activities.', '["The organization fails the organizational test because its governing documents authorize purposes beyond those in Section 501(c)(3), even though it passes the operational test", "The organization fails the operational test because 95% is not sufficient to qualify as exclusively operated for exempt purposes", "The organization fails because it must operate for a single exempt purpose, not multiple purposes", "The organization fails because educational programs for underprivileged youth do not qualify as exempt purposes"]'::jsonb, 0, 'Under Treasury Regulation 1.501(c)(3)-1(b)(1)(i), the organizational test requires that governing documents limit the organization''s purposes to those listed in Section 501(c)(3). The phrase ''any other lawful purposes'' is impermissibly broad — it authorizes non-exempt activities beyond an insubstantial part. Despite 95% charitable operations satisfying the operational test, the organizational test failure is independently disqualifying. Unlike choice B, the operational test requires primary, not 100%, dedication to exempt purposes.', 'hard', 4),

-- Q24: easy / L1 — Maximum excise tax on organization manager per transaction under Section 4958
(3, 'Tax-Exempt Organizations', 'What is the maximum excise tax per transaction on an organization manager who knowingly participates in an excess benefit transaction under Section 4958?', '["10% of the excess benefit with no cap", "25% of the excess benefit", "$20,000", "$50,000"]'::jsonb, 2, 'Under IRC Section 4958(a)(2), an organization manager who knowingly participates in an excess benefit transaction faces a 10% excise tax on the excess benefit, capped at $20,000 per transaction. This cap limits the manager''s personal exposure even for very large excess benefit amounts. Unlike choice A, the 10% tax is subject to the $20,000 per-transaction ceiling.', 'easy', 1),

-- Q25: easy / L1 — Section 501(c)(3) exempt purposes enumeration
(3, 'Tax-Exempt Organizations', 'Which of the following is an exempt purpose under Section 501(c)(3)?', '["Operating a commercial enterprise for profit", "Providing legal representation exclusively to corporate clients", "Engaging in political campaign activities for public office candidates", "Testing for public safety"]'::jsonb, 3, 'Under IRC Section 501(c)(3), testing for public safety is one of the specifically enumerated exempt purposes, along with religious, charitable, scientific, literary, educational, fostering amateur sports competition, and prevention of cruelty to children or animals. Unlike choice C, political campaign activity is absolutely prohibited for 501(c)(3) organizations and is not an exempt purpose.', 'easy', 1),

-- Q26: medium / L2 — Penalty for failure to file Form 990 ($20/day)
(3, 'Tax-Exempt Organizations', 'Mountain View Literacy Project, a 501(c)(3) with annual gross receipts of $350,000, files its Form 990 sixty days late without reasonable cause. Under Section 6652, what penalty does the organization face?', '["No penalty because the organization''s gross receipts are under $500,000", "$1,200 ($20 per day for 60 days)", "$6,000 ($100 per day for 60 days)", "Automatic revocation of tax-exempt status"]'::jsonb, 1, 'Under IRC Section 6652(c)(1)(A), the penalty for late filing of Form 990 is $20 per day (up to the lesser of $10,500 or 5% of gross receipts) for organizations with gross receipts under $1,186,000. At $20 per day for 60 days, Mountain View owes $1,200. Unlike choice C, the $100 per day rate applies only to organizations with gross receipts of $1,186,000 or more.', 'medium', 2),

-- Q27: medium / L2 — Section 509(a)(2) gross receipts test for public charity
(3, 'Tax-Exempt Organizations', 'Harmony Music Workshop, a 501(c)(3), receives $200,000 annually: $90,000 from workshop fees related to its exempt mission, $60,000 from public donations, and $50,000 from investment income. Under Section 509(a)(2), does Harmony qualify as a public charity based on the gross receipts test?', '["Yes, because contributions plus related gross receipts ($150,000) exceed one-third of total support ($66,667)", "No, because workshop fees are treated as unrelated business income", "No, because investment income exceeding 20% of total support disqualifies the organization", "Yes, but only if the organization has been in existence for at least five years"]'::jsonb, 0, 'Under IRC Section 509(a)(2), an organization qualifies as a public charity if it normally receives more than one-third of its support from contributions, membership fees, and gross receipts from activities related to its exempt function. Here, $60,000 (donations) + $90,000 (related gross receipts) = $150,000, which is 75% of total support — well above one-third. Unlike choice B, workshop fees related to the exempt mission are qualifying support, not UBI.', 'medium', 2),

-- Q28: easy / L1 — Form 990-N (e-Postcard) gross receipts threshold
(3, 'Tax-Exempt Organizations', 'What is the maximum gross receipts threshold for an exempt organization to file Form 990-N (e-Postcard)?', '["$50,000", "$100,000", "$200,000", "$500,000"]'::jsonb, 0, 'Under IRC Section 6033(i), exempt organizations with annual gross receipts normally $50,000 or less may file Form 990-N, a simplified electronic notice requiring only basic information such as name, address, and EIN. Unlike choice C, the $200,000 threshold applies to Form 990-EZ eligibility, not Form 990-N.', 'easy', 1),

-- Q29: medium / L3 — Excess business holdings combined 20% test with disqualified persons
(3, 'Tax-Exempt Organizations', 'Caldwell Family Foundation, a private foundation, owns 12% of the voting stock of Meridian Corp. The foundation''s disqualified persons (family members and controlled entities) collectively own an additional 15% of Meridian''s voting stock. Under Section 4943, does the foundation have excess business holdings?', '["No, because the foundation''s 12% ownership alone is below the 20% threshold", "Yes, because the combined holdings of 27% exceed the 20% permitted holding limit for the foundation and its disqualified persons", "No, because only the foundation''s direct holdings count toward the excess business holdings test", "Yes, but only if the foundation actively participates in managing Meridian Corp"]'::jsonb, 1, 'Under IRC Section 4943(c)(2), the combined voting stock held by a private foundation and all disqualified persons generally cannot exceed 20%. Here, 12% (foundation) + 15% (disqualified persons) = 27%, which exceeds the 20% threshold by 7%. The 7% excess is subject to a 10% excise tax. Unlike choice A, the test aggregates the foundation''s holdings with those of all disqualified persons, not just the foundation''s direct ownership.', 'medium', 3),

-- Q30: medium / L3 — Self-dealing: rent-free use of foundation property by disqualified person
(3, 'Tax-Exempt Organizations', 'Henderson Medical Foundation, a private foundation, allows its founder to use the foundation''s vacant office suite rent-free for his personal consulting business. The founder argues this is permissible because the foundation receives no below-market consideration and the space would otherwise sit empty. Under Section 4941, is this arrangement self-dealing?', '["No, because the founder is not paying rent, so there is no economic transaction to evaluate", "No, because the foundation suffers no financial harm since the space would be vacant regardless", "Yes, because any use of foundation property by a disqualified person constitutes self-dealing regardless of whether rent is charged or the property would otherwise be idle", "Yes, but only if the founder''s use of the space generates income exceeding $10,000 annually"]'::jsonb, 2, 'Under IRC Section 4941(d)(1)(A), the use of foundation assets by a disqualified person constitutes self-dealing regardless of whether the use is at FMV, rent-free, or on property that would otherwise be idle. Self-dealing is determined by the nature of the transaction, not by economic harm to the foundation. Unlike choice B, the absence of financial harm does not negate the prohibition — any use of foundation property by a disqualified person is per se self-dealing.', 'medium', 3)
;

COMMIT;
